from PIL import Image,ImageOps,ImageEnhance
from pathlib import Path
import base64, html
root=Path(__file__).resolve().parent.parent / 'referencias' / 'telas_originais'
assets={
 'blank':('04_geracao_configuracao.png',(323,130,997,892)),
 'mapped':('03_geracao_campos_selecionados.png',(320,130,997,892)),
 'result':('05_resultados_visualizador_pdf.png',(865,203,1452,869)),
 'realism':('08_realismo_antes_depois.png',(963,142,1596,894)),
}
encoded={}
for k,(f,crop) in assets.items():
 im=Image.open(root/f).convert('RGB').crop(crop)
 # moderate compression for a portable file
 im.thumbnail((750,1100))
 import io
 buff=io.BytesIO();im.save(buff,'JPEG',quality=80,optimize=True)
 encoded[k]='data:image/jpeg;base64,'+base64.b64encode(buff.getvalue()).decode()
print({k:len(v) for k,v in encoded.items()})
